import{_ as n,o as t,c as i,a3 as r}from"./chunks/framework.BlfGB29P.js";const a="/eep/ini-edit-translate-2026/editor-de.png",b=JSON.parse('{"title":"INI Edit Translate 2026","description":"Funktionsbeschreibung des Windows-Editors für EEP-Modell-INI-Dateien und Installation.eep mit ChatGPT-Übersetzung.","frontmatter":{"title":"INI Edit Translate 2026","description":"Funktionsbeschreibung des Windows-Editors für EEP-Modell-INI-Dateien und Installation.eep mit ChatGPT-Übersetzung."},"headers":[],"relativePath":"eep/ini-edit-translate-2026/index.md","filePath":"eep/ini-edit-translate-2026/index.md","lastUpdated":1792754181000}'),d={name:"eep/ini-edit-translate-2026/index.md"};function s(l,e,o,u,h,c){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="ini-edit-translate-2026" tabindex="-1">INI Edit Translate 2026 <a class="header-anchor" href="#ini-edit-translate-2026" aria-label="Permalink to &quot;INI Edit Translate 2026&quot;">​</a></h1><p><strong>Version 2.1.35.0 · Windows 11 · .NET Framework 4.8</strong></p><p>INI Edit Translate 2026 bearbeitet Modellbeschreibungen und Installationsdateien für EEP. Die Anwendung wird von Uwe Grimm / UGSo Software entwickelt und unter der MIT-Lizenz veröffentlicht.</p><p><a href="https://github.com/rockbaer2007/ini-edit-translate-2026" target="_blank" rel="noreferrer">Quellcode und README auf GitHub</a></p><p><img src="'+a+'" alt="Geprüfte deutsche Programmoberfläche ohne private Inhalte"></p><h2 id="funktionen" tabindex="-1">Funktionen <a class="header-anchor" href="#funktionen" aria-label="Permalink to &quot;Funktionen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Bereich</th><th>Möglichkeiten</th></tr></thead><tbody><tr><td>Modelltexte</td><td>Namen und Beschreibungen in EN/DE/FR/PL bearbeiten</td></tr><tr><td>Modellmetadaten</td><td>PDF-Verweise, Generation, Einsatzzeitraum, Land und Symbol bearbeiten</td></tr><tr><td>Bewegungsachsen und Signalfunktionen</td><td>Sprachabhängige Einträge anzeigen, bearbeiten und übersetzen</td></tr><tr><td>Installation.eep</td><td>Namen und Beschreibungen der unterstützten Installationsabschnitte bearbeiten</td></tr><tr><td>Vorschau</td><td>Originaldatei und erzeugte Dateivorschau vergleichen</td></tr><tr><td>Tabellenexport</td><td>Vollständige Tabellen als tabulatorgetrennte UTF-8-Dateien mit BOM exportieren</td></tr><tr><td>Sicherungen</td><td>Vor dem Überschreiben vorhandener INI-Dateien eine Kopie mit Originaldateinamen anlegen</td></tr></tbody></table><h2 id="chatgpt-ubersetzung" tabindex="-1">ChatGPT-Übersetzung <a class="header-anchor" href="#chatgpt-ubersetzung" aria-label="Permalink to &quot;ChatGPT-Übersetzung&quot;">​</a></h2><p>Die Anwendung verwendet ausschließlich die OpenAI Responses API. Pro Originaltext werden die drei anderen Zielsprachen gemeinsam angefordert. Es gibt keine Zwischenübersetzung über Englisch. Wiederholte Texte innerhalb derselben Aktion verwenden einen flüchtigen Cache.</p><p>Ein Fortschrittsdialog bietet <strong>Abbrechen</strong>. Das Anfragezeitlimit beträgt 60 Sekunden; maximal 24.000 Zeichen werden je Text akzeptiert. Unvollständige Antworten, fehlende Zielsprachen und veränderte Platzhalter wie <code>{0}</code>, <code>%s</code> oder <code>[e]</code> werden abgelehnt. Bei einem Fehler bleiben die vor der Übersetzung vorhandenen Texte und Tabellen erhalten.</p><p>Die Oberfläche wurde in DE/EN/FR auf beschädigte Zeichen, falsche Sprachzuordnungen und Sprachmischungen geprüft. Technische INI-Schlüssel wie <code>Name_GER</code> bleiben erhalten.</p><h2 id="einrichtung-und-bedienung" tabindex="-1">Einrichtung und Bedienung <a class="header-anchor" href="#einrichtung-und-bedienung" aria-label="Permalink to &quot;Einrichtung und Bedienung&quot;">​</a></h2><ol><li>Das Repository mit Visual Studio 2026, .NET-Desktopentwicklung und dem .NET Framework 4.8 Developer Pack bauen. Die Befehle stehen in der README.</li><li><code>INI Edit Translate 2026.exe</code> aus dem Release-Ordner starten. DLLs und Sprachordner müssen bei der Anwendung bleiben.</li><li>Unter <strong>Über → Einstellungen → OpenAI-Übersetzung</strong> den eigenen API-Schlüssel und das Modell eintragen. Voreinstellung ist <code>gpt-4.1-mini</code>.</li><li>Eine gesicherte eigene Datei zunächst im Modus <strong>Nur einlesen</strong> öffnen.</li><li>Für die Übersetzung <strong>Einlesen und übersetzen</strong> oder eine Übersetzungsschaltfläche verwenden. Bei Bewegungsachsen und Signalfunktionen die Ausgangssprache auswählen.</li><li>Vorschau und Modelltexte prüfen und anschließend ausdrücklich speichern.</li></ol><h2 id="daten-und-datenschutz" tabindex="-1">Daten und Datenschutz <a class="header-anchor" href="#daten-und-datenschutz" aria-label="Permalink to &quot;Daten und Datenschutz&quot;">​</a></h2><p>Die neue Fassung importiert keine alten Registrierungen oder privaten Datenbanken. Einstellungen werden getrennt pro Windows-Benutzer gespeichert. OpenAI-Konfiguration und Dateisicherungen liegen unter <code>%LOCALAPPDATA%/UGSo/IET2026/</code>.</p><p>Der Schlüssel wird für das Windows-Konto mit DPAPI verschlüsselt. Nur ausdrücklich übersetzte Texte werden an OpenAI gesendet; die API-Anfrage setzt <code>store: false</code>. Internet und separate API-Abrechnung sind erforderlich. Ein ChatGPT-Abonnement ersetzt die API-Abrechnung nicht.</p><h2 id="updatefunktion-und-prufstand" tabindex="-1">Updatefunktion und Prüfstand <a class="header-anchor" href="#updatefunktion-und-prufstand" aria-label="Permalink to &quot;Updatefunktion und Prüfstand&quot;">​</a></h2><p><strong>Die Updatefunktion ist vorerst vollständig deaktiviert.</strong> Weder eine automatische Verbindung zum bisherigen Updateserver noch ein Update-Menüpunkt ist enthalten. Google, LEO, Linguee und DeepL werden nicht mehr angeboten.</p><p>30 lokale Prüfungen mit simulierten API-Antworten sowie Debug- und Release-Builds prüfen Fehlerfälle, Abbruch, Wiederherstellung, Tabellenexport und die gerenderten Oberflächen in DE/EN/FR. Die Tests senden keine Texte an OpenAI. Ein echter API-Aufruf und die Qualität erzeugter Modellübersetzungen sind mit dem eigenen Zugang noch zu prüfen. Nicht jedes denkbare INI-Schema wird unterstützt; die inhaltliche Prüfung bleibt notwendig.</p>',19)])])}const p=n(d,[["render",s]]);export{b as __pageData,p as default};
